1	// Andes-CSR capability gating. A core implements only the Andes CSRs its
2	// config.inc enables; restoring a CSR the core lacks can hang the DMI
3	// handshake (observed on ax45mpv_premium: ucode + mecc_code). So the
4	// resume/drain loops transport only the CSRs the target core supports. This
5	// pins the CSR-address -> feature-gate map and the premium subset.
6	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
7	#include "doctest.h"
8	
9	#include "hybrid/andes_caps.hpp"
10	#include "hybrid/state_abi.h"
11	
12	#include <algorithm>
13	#include <string>
14	#include <vector>
15	
16	using hybrid::AndesCaps;
17	using hybrid::AndesGate;
18	
19	// ax45mpv_premium config.inc: CoDense + ILM + DLM + perf monitor on
20	// (NDS_PERFORMANCE_MONITOR_INT=1); NDS_SSCOFPMF_SUPPORT=0 so the Andes PMNDS
21	// counter scheme is live (PMNDS gate on); DSP, ECC, PowerBrake, StackSafe,
22	// PMA off; M-only (NDS_NUM_PRIVILEGE_LEVELS=1 -> UMODE + PMNDS_UMODE off).
23	static AndesCaps premium()
24	{
25	  AndesCaps c = AndesCaps::none();
26	  c.set(AndesGate::CODENSE);
27	  c.set(AndesGate::ILM);
28	  c.set(AndesGate::DLM);
29	  c.set(AndesGate::PERF_MONITOR);
30	  c.set(AndesGate::PMNDS);
31	  c.set(AndesGate::CCTL);    // 64K I$/D$ -> cache CCTL CSRs exist
32	  c.set(AndesGate::ALT_FP);  // NDS_BFLOAT16_ARITH_SUPPORT=1 + ACE
33	  return c;
34	}
35	
36	// ax46mpv_advanced config.inc: perf monitor on BUT NDS_SSCOFPMF_SUPPORT=1 --
37	// the standard Sscofpmf scheme replaces the Andes PMNDS counter CSRs, so the
38	// PMNDS gates stay off. CoDense + ILM + DLM + PMA on; M-only.
39	static AndesCaps advanced()
40	{
41	  AndesCaps c = AndesCaps::none();
42	  c.set(AndesGate::CODENSE);
43	  c.set(AndesGate::ILM);
44	  c.set(AndesGate::DLM);
45	  c.set(AndesGate::PERF_MONITOR);
46	  c.set(AndesGate::PMA);
47	  c.set(AndesGate::TRIGGER);
48	  c.set(AndesGate::CCTL);    // 64K I$/D$
49	  c.set(AndesGate::ALT_FP);  // BF16 arith + ACE
50	  return c;
51	}
