53	TEST_CASE("registration audit: the three under-claim classes are gated right")
54	{
55	  // Found by the ax46mpv_advanced registration audit (both engines'
56	  // kv_csr_dec.v existent_csr agree with the SPA on all three):
57	  // 1. mnvec 0x7C3: spec "IM Requirement: Required", RTL unconditional --
58	  //    it is base Andes NMI state, NOT part of Smrnmi (0x740-0x744, which
59	  //    these cores genuinely lack).
60	  CHECK(AndesCaps::none().supports_csr(0x7C3));   // ALWAYS
61	  // 2. mcctlbeginaddr/mcctldata: exist with the cache RAMs (RTL:
62	  //    CACHE_SUPPORT_INT), on BOTH engines; the old binding pointed at
63	  //    NDS_CCTLCSR macros no config generation emits.
64	  CHECK(premium().supports_csr(0x7CB));
65	  CHECK(advanced().supports_csr(0x7CD));
66	  CHECK_FALSE(AndesCaps::none().supports_csr(0x7CB));  // cache-less core
67	  // 3. umisc_ctl 0x813: spec ALT_FP_FMT|CST_CTL, RTL BF16_ARITH|ACE --
68	  //    "Access Mode: User and above" is who may TOUCH it, not an existence
69	  //    condition; the old UMODE gate dropped it on both (M-only) engines.
70	  CHECK(premium().supports_csr(0x813));
71	  CHECK(advanced().supports_csr(0x813));
72	  AndesCaps umode_only = AndesCaps::none();
73	  umode_only.set(AndesGate::UMODE);
74	  CHECK_FALSE(umode_only.supports_csr(0x813));    // U-mode alone: no
75	}
